#!/bin/bash
# kconfig/gen-params.sh - the bench parameters as Kconfig symbols
# =============================================================================
#   kconfig/gen-params.sh build OUT_FILE
#   kconfig/gen-params.sh start OUT_FILE [BUILD_CONFIG]
#
# Source: globals.conf.example, the reference of the parameters (network:
# MCC, MNC, KI, IMSI, ARFCN...; then the launcher variables generated by
# tools/globals-complet.py). Each VAR="x" becomes `config P_<VAR>`:
#   - its section ("# ── Radio ──") becomes a comment line of the menu;
#   - the comment lines above it become its prompt (first line) and help;
#   - "# choix : a | b | c" becomes a real choice (plus "defaut du script"
#     when the value may be empty), the value a hidden string P_<VAR>.
# Defaults: build -> the example's value; start -> the build's value
# (BUILD_CONFIG, CONFIG_P_<VAR>), else this machine's globals.conf, else the
# example: the start menu follows from the build.
# The network block goes into the main menu; the launcher variables (a
# hundred, expert) into a submenu. An empty string = the value computed by
# the scripts. tools/start-config.sh exports the non-empty ones (the
# environment wins over globals.conf, startup_scripts/03-affichage.sh).
# =============================================================================
set -uo pipefail
cd "$(dirname "$(readlink -f "$0")")/.."
MODE="${1:?build|start}"; OUT="${2:?fichier}"; BUILD_CONFIG="${3:-}"
EX="globals.conf.example"; GC="globals.conf"

conf_val() {   # conf_val FILE VAR -> value or nothing (status 1)
    [ -r "$1" ] || return 1
    local l; l="$(grep -m1 "^$2=" "$1")" || return 1
    l="${l#*=}"; l="${l#\"}"; l="${l%\"}"; printf '%s' "$l"
}
kconf_val() {  # kconf_val FILE SYMBOL -> value of CONFIG_SYMBOL (status 1 if absent)
    [ -r "$1" ] || return 1
    local l; l="$(grep -m1 "^CONFIG_$2=" "$1")" || return 1
    l="${l#*=}"; l="${l#\"}"; l="${l%\"}"; printf '%s' "$l"
}
# Kconfig string: \ and " escaped, $ as $(dollar) (kconfig/Kconfig.include:
# the preprocessor expands $(...) and has no $$).
q() { local s="$1"; s="${s//\\/\\\\}"; s="${s//\"/\\\"}"; printf '"%s"' "${s//\$/\$(dollar)}"; }
member() { local u; u="$(printf '%s' "$1" | tr -c 'A-Za-z0-9\n' '_' | tr a-z A-Z)"; echo "${u:-DEFAUT}"; }

default_of() {  # VAR example_value
    local v
    if [ "$MODE" = start ]; then
        if [ -n "$BUILD_CONFIG" ] && v="$(kconf_val "$BUILD_CONFIG" "P_$1")"; then printf '%s' "$v"; return; fi
        if v="$(conf_val "$GC" "$1")"; then printf '%s' "$v"; return; fi
    fi
    printf '%s' "$2"
}

emit() {  # VAR value help_lines choices
    local var="$1" val="$2" help="$3" choix="$4" prompt def c m first=1
    prompt="$(printf '%s\n' "$help" | sed -n '1p')"; [ -n "$prompt" ] || prompt="$var"
    prompt="$var : $prompt"; [ "${#prompt}" -gt 70 ] && prompt="${prompt:0:67}..."
    def="$(default_of "$var" "$val")"
    if [ -n "$choix" ]; then
        local items=() it found=0
        IFS='|' read -r -a items <<<"$choix"
        echo "choice"
        echo "	prompt $(q "$prompt")"
        for it in "${items[@]}"; do it="$(echo "$it" | sed 's/^ *//;s/ *$//')"; [ "$it" = "$def" ] && found=1; done
        if [ "$found" = 1 ]; then echo "	default P_${var}__$(member "$def")"
        else echo "	default P_${var}__DEFAUT"; fi
        echo "	help"; printf '%s\n' "$help" | sed 's/^/	  /'
        echo "	  Variable $var (globals.conf)."
        echo
        if [ "$found" = 0 ] || [ -z "$val" ]; then
            echo "config P_${var}__DEFAUT"
            if [ -n "$def" ] && [ "$found" = 0 ]; then echo "	bool $(q "$def (valeur actuelle)")"
            else echo "	bool \"(defaut du script)\""; fi
        fi
        for it in "${items[@]}"; do
            it="$(echo "$it" | sed 's/^ *//;s/ *$//')"; [ -n "$it" ] || continue
            echo "config P_${var}__$(member "$it")"; echo "	bool $(q "$it")"
        done
        echo "endchoice"; echo
        echo "config P_$var"; echo "	string"
        for it in "${items[@]}"; do
            it="$(echo "$it" | sed 's/^ *//;s/ *$//')"; [ -n "$it" ] || continue
            echo "	default $(q "$it") if P_${var}__$(member "$it")"
        done
        echo "	default $(q "$([ "$found" = 0 ] && printf '%s' "$def")")"
    else
        echo "config P_$var"
        echo "	string $(q "$prompt")"
        echo "	default $(q "$def")"
        echo "	help"; printf '%s\n' "$help" | sed 's/^/	  /'
        echo "	  Variable $var (globals.conf). Vide = valeur calculee par les scripts."
    fi
    echo
}

{
    echo "# GENERATED by kconfig/gen-params.sh ($MODE) from $EX - do not edit"
    echo
    echo 'comment "--- Parametres du banc (globals.conf) ---"'
    echo
    help=""; choix=""; lanceur=0
    while IFS= read -r l || [ -n "$l" ]; do
        case "$l" in
            "# >>> VARIABLES DU LANCEUR"*)
                lanceur=1; echo 'menu "Variables du lanceur (avance, vide = defaut du script)"'; echo
                help=""; choix="" ;;
            "# <<<"*) ;;
            "# ── "*)
                t="$(echo "$l" | sed 's/^# ── //;s/ ─*$//')"
                echo "comment $(q "$t")"; echo; help=""; choix="" ;;
            "# ═"*|"#") help=""; choix="" ;;
            "# choix : "*) choix="${l#\# choix : }" ;;
            "# "*) help="${help:+$help
}${l#\# }" ;;
            [A-Za-z_]*=*)
                var="${l%%=*}"; val="${l#*=}"; val="${val#\"}"; val="${val%\"}"
                [[ "$var" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] && emit "$var" "$val" "$help" "$choix"
                help=""; choix="" ;;
            *) help=""; choix="" ;;
        esac
    done <"$EX"
    [ "$lanceur" = 1 ] && echo "endmenu"
} >"$OUT.tmp" && { cmp -s "$OUT.tmp" "$OUT" && rm -f "$OUT.tmp" || mv -f "$OUT.tmp" "$OUT"; }
